import type { WerkbakId, WerkbakNaam } from "#helpers/werkbakken";
export type { WerkbakId, WerkbakNaam };

type Brand<T, Naam extends string> = T & { readonly __type: Naam };
type SBrand<Naam extends string> = Brand<string, Naam>;
type Id<Naam extends string> = Brand<`${number}`, Naam>;

// Identifiers van diverse objecten in Axon
export type PakketId = Id<"PakketId">;
export type PolisId = Id<"PolisId">;
export type PolisVersieId = Id<"PolisVersieId">;
export type PakketVersieId = Id<"PakketVersieId">;
export type CommunicatieId = Id<"CommunicatieId">;
export type DocumentId = Id<"DocumentId">;
export type BoekingId = Id<"BoekingId">;
export type OpgaveId = Id<"OpgaveId">;
export type ClaimId = Id<"ClaimId">;
export type IntermediairId = Id<"IntermediairId">;
export type KlantId = Id<"KlantId">;

// Types van producten en componenten
export type PakketSoort = "garage";
export type PakketProductNaam = "Garageverzekering";
export type PolisProductNaam = "Garage";
export type PolisProductExtId = "garage";
export type ClausuleType = SBrand<"ClausuleType">;
export type ClausuleNaam = SBrand<"ClausuleNaam">;

// Flags van diverse objecten in Axon
export type PolisStatusNaam = "active" | "coverageRevoked" | "deactivated";
export type PolisStatusExitId = "Actief";
export type PakketStatusNaam = "Actief";
export type ApplicationType = "Mutatie";

// Gebruikersgegevens
export type AxonGebruiker = SBrand<"AxonGebruiker">

/** Gegevens gekoppeld aan een persoon */
export type PersoonNaam = SBrand<"PersoonNaam">;
