export type Stad = SBrand<"Stad">;
export type Straat = SBrand<"Straat">;
export type Postcode = SBrand<"Postcode">
export type TelefoonNummer = SBrand<"Telefoonnummer">;
export type KvkNummer = Id<"KvkNummer">

export type DateString = `${number}-${number}-${number}`;
export type TimeString = `${number}:${number}:${number}`;
export type ChangeToken = Brand<`${DateString} ${TimeString}.${number}`, " ChangeToken">;
export type EmailAdres = Brand<`${string}@${string}.${string}`, "EmailAdres">;
export type FileName = `${string}.${string}`;
export type Geldbedrag = Brand<number, "Geldbedrag">
export type Promillage = Brand<number, "Promillage">

export type CookieJar = Record<string, string>;
